import { describe, it, expect } from 'vitest';
import tool from './dds-inspector.tool';

const DDS_B64 =
  '';

const DDS_HEADER = {
  size: 2856,
  header_size: 124,
  flags: 4103,
  w: 64,
  h: 64,
  pitch: 4096,
  depth: 1,
  mipcount: 5,
  fourcc: 827611204,
  ddspf_flags: 4,
  caps: 4096,
};

const META = tool.meta;

function b64(s: string): Uint8Array {
  const bin = atob(s);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i += 1) out[i] = bin.charCodeAt(i);
  return out;
}

function fileOf(bytes: Uint8Array, name = 'x.dds'): File {
  const copy = new Uint8Array(bytes);
  return new File([copy.buffer as ArrayBuffer], name, { type: 'image/vnd.ms-dds' });
}

async function rowsOf(
  f: File,
  options: Record<string, string | number | boolean> = {},
): Promise<string[][]> {
  const r = await tool.run({ files: [f], options });
  const parsed = JSON.parse(r.report?.output ?? '{"rows":[]}');
  return (parsed.rows ?? []) as string[][];
}

describe('dds-inspector', () => {
  it('declares on-device privacy and no network', () => {
    expect(META.privacy.processing).toBe('on-device');
    expect(META.privacy.network).toBe('none');
    expect(META.privacy.offline).toBe(true);
  });

  it('reads the header into the summary view', async () => {
    const rows = await rowsOf(fileOf(b64(DDS_B64), 'tex.dds'), { view: 'summary' });
    const m = new Map<string, string>(rows.map((r) => [r[0] ?? '', r[1] ?? '']));
    expect(m.get('File size')).toBe(String(DDS_HEADER.size) + ' B');
    expect(m.get('Magic')).toBe('DDS (valid)');
    expect(m.get('Dimensions')).toBe(String(DDS_HEADER.w) + ' x ' + String(DDS_HEADER.h));
    expect(m.get('Format')).toBe('DXT1 (BC1)');
    expect(m.get('Mipmap levels')).toBe(String(DDS_HEADER.mipcount));
    expect(m.get('Caps')).toBe('0x1000');
  });

  it('decodes the header fields view', async () => {
    const rows = await rowsOf(fileOf(b64(DDS_B64), 'tex.dds'), { view: 'header' });
    const h = new Map<string, string>(rows.map((r) => [r[0] ?? '', r[1] ?? '']));
    expect(h.get('Header size')).toBe(String(DDS_HEADER.header_size));
    expect(h.get('Width')).toBe(String(DDS_HEADER.w));
    expect(h.get('Height')).toBe(String(DDS_HEADER.h));
    expect(h.get('Mipmap count')).toBe(String(DDS_HEADER.mipcount));
    expect(h.get('fourCC')).toBe('DXT1 (BC1) (0x' + DDS_HEADER.fourcc.toString(16) + ')');
    expect(h.get('Pixel format flags')).toBe('0x' + DDS_HEADER.ddspf_flags.toString(16));
  });

  it('translates the fourCC and reports flags', async () => {
    const rows = await rowsOf(fileOf(b64(DDS_B64), 'tex.dds'), { view: 'summary' });
    const m = new Map<string, string>(rows.map((r) => [r[0] ?? '', r[1] ?? '']));
    expect(m.get('Format')).toBe('DXT1 (BC1)');
    expect(m.get('Pixel format flags')).toBe('0x' + DDS_HEADER.ddspf_flags.toString(16));
  });

  it('flags a bad magic', async () => {
    const rows = await rowsOf(fileOf(new Uint8Array([1, 2, 3, 4]), 'bad.dds'), {
      view: 'findings',
    });
    expect(rows.some((r) => r[1] === 'magic')).toBe(true);
  });

  it('throws a user-facing error when no file is given', async () => {
    await expect(tool.run({ files: [], options: {} })).rejects.toThrow(/DDS/);
  });
});
